    const double x = static_cast<double>(arguments[2].Float());
    const double y = static_cast<double>(arguments[3].Float());
    const double z = static_cast<double>(arguments[4].Float());
    const double xa = static_cast<double>(arguments[5].Float());
    const double ya = static_cast<double>(arguments[6].Float());
    const double za = static_cast<double>(arguments[7].Float());
    const std::string params_bytes = arguments[8].String();
    const unsigned int params_count = static_cast<unsigned int>(params_bytes.size() / sizeof(int));
    int* params_data = new int[params_count + 1];
