bool ModApi_level_getEntities(Level* self, const mod::Value* arguments, mod::Value* result)
{
    (void)arguments;
    (void)result;
    boost::shared_ptr<Entity> excluded_entity;
    if (arguments[0].Id() != 0 && !ModHandles::Get(arguments[0].Id(), &excluded_entity))
        return false;
    boost::shared_ptr<Entity> excluded = boost::dynamic_pointer_cast<Entity>(excluded_entity);
    AABB* box = NULL;
    if (!ModHandles::Get(arguments[1].Id(), &box))
        return false;
    const std::vector<boost::shared_ptr<Entity> >* modList = self->getEntities(excluded, box, NULL);
    std::string modIds;
    for (size_t modAt = 0; modList != NULL && modAt < modList->size(); ++modAt)
        modIds += (modIds.empty() ? "" : "\n") + boost::lexical_cast<std::string>((*modList)[modAt]->getId());
    *result = mod::Value::FromString(modIds);
    return true;
}

