bool ModApi_level_explode(Level* self, const mod::Value* arguments, mod::Value* result)
{
    (void)arguments;
    (void)result;
    boost::shared_ptr<Entity> source_entity;
    if (arguments[0].Id() != 0 && !ModHandles::Get(arguments[0].Id(), &source_entity))
        return false;
    boost::shared_ptr<Entity> source = boost::dynamic_pointer_cast<Entity>(source_entity);
    const double x = static_cast<double>(arguments[1].Float());
    const double y = static_cast<double>(arguments[2].Float());
    const double z = static_cast<double>(arguments[3].Float());
    const float radius = static_cast<float>(arguments[4].Float());
    const bool fire = static_cast<bool>(arguments[5].Bool());
    const bool breaksBlocks = static_cast<bool>(arguments[6].Bool());
    const bool playersOnly = static_cast<bool>(arguments[7].Bool());
    const bool noBlockDrops = static_cast<bool>(arguments[8].Bool());
    const bool silent = static_cast<bool>(arguments[9].Bool());
    const float damageRadius = static_cast<float>(arguments[10].Float());
    const boost::shared_ptr<Explosion> modOwner = self->explode(source, x, y, z, radius, fire, breaksBlocks, playersOnly, noBlockDrops, silent, damageRadius);
    const uint32_t modId = modOwner ? ModHandles::AddShared(modOwner) : 0;
    if (modId != 0)
        *result = mod::Value::FromHandle(mod::api::eHandle_Explosion, modId);
    return true;
}

