bool ModApi_level_getAllEntities(Level* self, const mod::Value* arguments, mod::Value* result)
{
    (void)arguments;
    (void)result;
    const std::vector<boost::shared_ptr<Entity> > modList = self->getAllEntities();
    std::string modIds;
    for (size_t modAt = 0; modAt < modList.size(); ++modAt)
        modIds += (modIds.empty() ? "" : "\n") + boost::lexical_cast<std::string>(modList[modAt]->getId());
    *result = mod::Value::FromString(modIds);
    return true;
}

