bool ModApi_Item_useOn(Item* self, const mod::Value* arguments, mod::Value* result)
{
    (void)arguments;
    (void)result;
    boost::shared_ptr<Entity> player_entity;
    if (arguments[0].Id() != 0 && !ModHandles::Get(arguments[0].Id(), &player_entity))
        return false;
    boost::shared_ptr<Player> player = boost::dynamic_pointer_cast<Player>(player_entity);
    Level* level = NULL;
    if (!ModHandles::Get(arguments[1].Id(), &level))
        return false;
    const BlockPos pos(static_cast<int>(arguments[2].Int()), static_cast<int>(arguments[3].Int()), static_cast<int>(arguments[4].Int()));
    const InteractionHand::EInteractionHand hand = static_cast<InteractionHand::EInteractionHand>(arguments[5].Int());
    Direction* direction = NULL;
    if (!ModHandles::Get(arguments[6].Id(), &direction))
        return false;
    const float hitX = static_cast<float>(arguments[7].Float());
    const float hitY = static_cast<float>(arguments[8].Float());
    const float hitZ = static_cast<float>(arguments[9].Float());
    const bool simulate = static_cast<bool>(arguments[10].Bool());
    *result = mod::Value::FromInt(static_cast<int>(self->useOn(player, level, pos, hand, direction, hitX, hitY, hitZ, simulate)));
    return true;
}

