bool ModApi_entity_getHandSlots(boost::shared_ptr<Entity> self, const mod::Value* arguments, mod::Value* result)
{
    (void)arguments;
    (void)result;
    Entity* object = dynamic_cast<Entity*>(self.get());
    if (object == NULL)
        return false;
    const NonNullList<not_null_ptr<ItemInstance> >& modList = object->getHandSlots();
    std::vector<mod::Value> modItems;
    for (unsigned int modAt = 0; modAt < static_cast<unsigned int>(modList.size()); ++modAt)
    {
        const boost::shared_ptr<ItemInstance> modOwner = modList[modAt];
        const uint32_t modId = modOwner ? ModHandles::AddShared(modOwner) : 0;
        modItems.push_back(modId != 0 ? mod::Value::FromHandle(mod::api::eHandle_ItemInstance, modId) : mod::Value());
    }
    *result = mod::Value::FromList(modItems);
    return true;
}

