bool ModApi_entity_getSubEntities(boost::shared_ptr<Entity> self, const mod::Value* arguments, mod::Value* result)
{
    (void)arguments;
    (void)result;
    Entity* object = dynamic_cast<Entity*>(self.get());
    if (object == NULL)
        return false;
    const std::vector<boost::shared_ptr<Entity> >* modList = object->getSubEntities();
    std::string modIds;
    for (size_t modAt = 0; modList != NULL && modAt < modList->size(); ++modAt)
        modIds += (modIds.empty() ? "" : "\n") + boost::lexical_cast<std::string>((*modList)[modAt]->getId());
    *result = mod::Value::FromString(modIds);
    return true;
}

