bool ModApi_entity_getTags(boost::shared_ptr<Entity> self, const mod::Value* arguments, mod::Value* result)
{
    (void)arguments;
    (void)result;
    Entity* object = dynamic_cast<Entity*>(self.get());
    if (object == NULL)
        return false;
    std::set<std::wstring>* modList = object->getTags();
    std::string modLines;
    for (std::set<std::wstring>::const_iterator it = modList->begin(); it != modList->end(); ++it)
        modLines += (modLines.empty() ? "" : "\n") + ModText::ToUtf8(*it);
    *result = mod::Value::FromString(modLines);
    return true;
}

