bool ModApi_entity_CanRecordStats(boost::shared_ptr<Entity> self, const mod::Value* arguments, mod::Value* result)
{
    (void)arguments;
    (void)result;
    Player* object = dynamic_cast<Player*>(self.get());
    if (object == NULL)
        return false;
    Stat* stat = NULL;
    if (!ModHandles::Get(arguments[0].Id(), &stat))
        return false;
    const std::string parameters_bytes = arguments[1].String();
    const unsigned int parameters_count = static_cast<unsigned int>(parameters_bytes.size() / sizeof(unsigned char));
    unsigned char* parameters_data = new unsigned char[parameters_count + 1];
    memcpy(parameters_data, parameters_bytes.data(), parameters_count * sizeof(unsigned char));
    arrayWithLength<unsigned char> parameters(parameters_data, parameters_count);
    *result = mod::Value::FromInt(object->CanRecordStats(stat, parameters));
    return true;
}

