bool ModApi_ChatCommand_getAliases(ChatCommand* self, const mod::Value* arguments, mod::Value* result)
{
    (void)arguments;
    (void)result;
    std::vector<std::wstring> modList = self->getAliases();
    std::string modLines;
    for (std::vector<std::wstring>::const_iterator it = modList.begin(); it != modList.end(); ++it)
        modLines += (modLines.empty() ? "" : "\n") + ModText::ToUtf8(*it);
    *result = mod::Value::FromString(modLines);
    return true;
}

