bool ModApi_painter_Wrap(MenuPainter* self, const mod::Value* arguments, mod::Value* result)
{
    (void)arguments;
    (void)result;
    const std::wstring text = ModText::FromUtf8(arguments[0].String());
    const int width = static_cast<int>(arguments[1].Int());
    std::vector<std::wstring> modList = self->Wrap(text, width);
    std::string modLines;
    for (std::vector<std::wstring>::const_iterator it = modList.begin(); it != modList.end(); ++it)
        modLines += (modLines.empty() ? "" : "\n") + ModText::ToUtf8(*it);
    *result = mod::Value::FromString(modLines);
    return true;
}

