bool ModApi_Inventory_new_static(const mod::Value* arguments, mod::Value* result)
{
    (void)arguments;
    (void)result;
    Player* player = NULL;
    boost::shared_ptr<Entity> player_entity;
    if (arguments[0].Kind() == mod::api::eHandle_entity)
    {
        if (!ModHandles::Get(arguments[0].Id(), &player_entity))
            return false;
        player = dynamic_cast<Player*>(player_entity.get());
        if (player == NULL)
            return false;
    }
    else if (!ModHandles::Get(arguments[0].Id(), &player))
        return false;
    Inventory* modResult = const_cast<Inventory*>(new Inventory(player));
    if (modResult != NULL)
        *result = mod::Value::FromHandle(mod::api::eHandle_Inventory, ModHandles::Add(modResult));
    return true;
}

