bool ModApi_BlockEntity_createMenu(BlockEntity* self, const mod::Value* arguments, mod::Value* result)
{
    (void)arguments;
    (void)result;
    ScriptedBlockEntity* object = dynamic_cast<ScriptedBlockEntity*>(self);
    if (object == NULL)
        return false;
    boost::shared_ptr<Inventory> inventory_owner;
    if (!ModHandles::GetShared(arguments[0].Id(), &inventory_owner))
        return false;
    boost::shared_ptr<Inventory> inventory(inventory_owner);
    boost::shared_ptr<Entity> player_entity;
    if (arguments[1].Id() != 0 && !ModHandles::Get(arguments[1].Id(), &player_entity))
        return false;
    boost::shared_ptr<Player> player = boost::dynamic_pointer_cast<Player>(player_entity);
    AbstractContainerMenu* modResult = const_cast<AbstractContainerMenu*>(object->createMenu(inventory, player));
    if (modResult != NULL)
        *result = mod::Value::FromHandle(mod::api::eHandle_AbstractContainerMenu, ModHandles::Add(modResult));
    return true;
}

